const char* enum_name(ContractDataDurability v) noexcept {
  switch (v) {
    case ContractDataDurability::TEMPORARY: return "TEMPORARY";
    case ContractDataDurability::PERSISTENT: return "PERSISTENT";
    default: return nullptr;
  }
}
bool enum_from_name(std::string_view s, ContractDataDurability& v) noexcept {
  if (s == "TEMPORARY") { v = ContractDataDurability::TEMPORARY; return true; }
  if (s == "PERSISTENT") { v = ContractDataDurability::PERSISTENT; return true; }
  return false;
}

bool Codec<ContractDataDurability>::encode(const ContractDataDurability& v, Encoder& e) {
  switch (v) {
    case ContractDataDurability::TEMPORARY:
    case ContractDataDurability::PERSISTENT:
      break;
    default: return e.fail(stellar::v1::ErrorCode::kEncodeFailed, "unknown enum value");
  }
  return e.i32(static_cast<std::int32_t>(v));
}
bool Codec<ContractDataDurability>::decode(ContractDataDurability& v, Decoder& d) {
  std::int32_t x;
  if (!d.i32(x)) return false;
  switch (x) {
    case 0: v = ContractDataDurability::TEMPORARY; return true;
    case 1: v = ContractDataDurability::PERSISTENT; return true;
    default: return d.fail(stellar::v1::ErrorCode::kDecodeFailed, "unknown enum value");
  }
}
bool Codec<ContractDataDurability>::gen(ContractDataDurability& v, XdrRng& r, std::uint32_t) {
  switch (r.index(2)) {
    case 0: v = ContractDataDurability::TEMPORARY; return true;
    case 1: v = ContractDataDurability::PERSISTENT; return true;
  }
  v = ContractDataDurability::TEMPORARY;
  return true;
}

