      return e.fail(stellar::v1::ErrorCode::kEncodeFailed, "LedgerEntryData: payload does not match discriminant");
    case LedgerEntryType::LIQUIDITY_POOL:
      if (const auto* p = std::get_if<5>(&v.v_)) { return e.i32(static_cast<std::int32_t>(v.t_)) && Codec<std::remove_cvref_t<decltype(*p)>>::encode(*p, e); }
      return e.fail(stellar::v1::ErrorCode::kEncodeFailed, "LedgerEntryData: payload does not match discriminant");
