bool Codec<LedgerEntryExt>::encode(const LedgerEntryExt& v, Encoder& e) {
  switch (v.t_) {
    case 0:
      return e.i32(static_cast<std::int32_t>(v.t_));
    case 1:
      if (const auto* p = std::get_if<1>(&v.v_)) { return e.i32(static_cast<std::int32_t>(v.t_)) && Codec<std::remove_cvref_t<decltype(*p)>>::encode(*p, e); }
      return e.fail(stellar::v1::ErrorCode::kEncodeFailed, "LedgerEntryExt: payload does not match discriminant");
    default: return e.fail(stellar::v1::ErrorCode::kEncodeFailed, "LedgerEntryExt: unknown discriminant");
  }
}

bool Codec<LedgerEntryExt>::decode(LedgerEntryExt& v, Decoder& d) {
  Decoder::DepthGuard g(d);
  if (!g) return false;
  std::int32_t tag;
  if (!d.i32(tag)) return false;
  switch (tag) {
    case 0:
      v.t_ = static_cast<std::int32_t>(tag);
      v.v_.template emplace<0>();
      return true;
    case 1:
      v.t_ = static_cast<std::int32_t>(tag);
      v.v_.template emplace<1>();
      return d.field("v1", std::get<1>(v.v_));
    default: return d.fail(stellar::v1::ErrorCode::kDecodeFailed, "LedgerEntryExt: unknown discriminant");
  }
}

bool Codec<LedgerEntryExt>::gen(LedgerEntryExt& v, XdrRng& r, std::uint32_t depth) {
  std::size_t i = depth >= 4 ? 0 : r.index(2);
  switch (i) {
    case 0: {
      v.t_ = 0;
      v.v_.template emplace<0>();
      return true;
    }
    case 1: {
      v.t_ = 1;
      auto& p = v.v_.template emplace<1>();
      return Codec<std::remove_reference_t<decltype(p)>>::gen(p, r, depth + 1);
    }
  }
  return false;
}

