      return e.fail(stellar::v1::ErrorCode::kEncodeFailed, "LedgerKey: payload does not match discriminant");
    case LedgerEntryType::DATA:
      if (const auto* p = std::get_if<3>(&v.v_)) { return e.i32(static_cast<std::int32_t>(v.t_)) && Codec<std::remove_cvref_t<decltype(*p)>>::encode(*p, e); }
      return e.fail(stellar::v1::ErrorCode::kEncodeFailed, "LedgerKey: payload does not match discriminant");
    case LedgerEntryType::CLAIMABLE_BALANCE:
